public void init()
{
    next init();

    if (METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole)))
    {
        FormDataSource InventItemPurchSetup_DS = this;
        InventItemPurchSetup_DS.insertIfEmpty(false);
    }
}

/// <summary>
/// Activates the form data source.
/// </summary>
/// <returns></returns>
public int active()
{
    int ret = next active();

    SecurityRights securityRights = SecurityRights::construct();

    AccessRight maxAccess = securityRights.formControlAccessRight(formStr(InventItemOrderSetup), formControlStr(InventItemOrderSetup, METSecurityControl));

    if (maxAccess == AccessRight::Edit && this.allowEdit())
    {
        this.disableControls();
    }

    return ret;
}

/// <summary>
/// Disables the specified controls on the form.
/// </summary>
private void disableControls()
{
    FormControl formControl;

    container nonEditableControls =
    [
        formControlStr(InventItemOrderSetup, InventItemPurchSetup_METPurchUnit),
        formControlStr(InventItemOrderSetup, PurchOtherGrp_M_editLeadTime),
        formControlStr(InventItemOrderSetup, PurchOtherGrp_M_editCalendarDays)
    ];

    int i;

    // Disable controls
    for (i = 1; i <= conLen(nonEditableControls); i++)
    {
        formControl = this.formRun().design().controlName(conPeek(nonEditableControls, i));

        if (formControl)
        {
            formControl.allowEdit(false);
        }
    }
}
